<section class="section"><p class="eyebrow">ONE STEP CLOSER</p><h1>Make it yours.</h1><?php $items=Commerce::cart(); if(!$items): ?><p>Your bag is empty.</p><a class="btn" href="/shop">Explore WIKI</a><?php else: $totals=Commerce::totals($items,$_SESSION['coupon']??''); ?><div class="checkout-grid"><form method="post" action="/checkout" class="checkout-form"><?=csrf_field()?><input type="hidden" name="action" value="checkout"><input type="hidden" name="checkout_key" value="<?=e($_SESSION['checkout_key'])?>"><h2>Contact & delivery</h2><?php if(!user()): ?><p>Checkout as a guest, or <a class="underlined" href="/login">sign in</a> for a quicker next visit.</p><?php endif ?><div class="form-grid"><?php foreach(['first_name'=>'First name','last_name'=>'Last name','email'=>'Email','phone'=>'Phone','country'=>'Country','province'=>'Province / state','city'=>'City','postal_code'=>'Postal code','address'=>'Street address'] as $key=>$label): ?><label class="<?=$key==='address'?'wide':''?>"><?=e($label)?><input name="<?=e($key)?>" type="<?=$key==='email'?'email':($key==='phone'?'tel':'text')?>" autocomplete="<?=e(['first_name'=>'given-name','last_name'=>'family-name','email'=>'email','phone'=>'tel','country'=>'country-name','province'=>'address-level1','city'=>'address-level2','postal_code'=>'postal-code','address'=>'street-address'][$key])?>" value="<?=e($key==='email'?(user()['email']??''):($key==='country'?'Pakistan':''))?>" required maxlength="<?=$key==='address'?500:($key==='email'?190:100)?>"></label><?php endforeach ?></div><label class="check"><input type="checkbox" name="different_billing" id="different-billing"> Use a different billing address</label><div class="form-grid" id="billing-fields" hidden><?php foreach(['country','province','city','postal_code','address'] as $key): ?><label><?=e(ucwords(str_replace('_',' ',$key)))?><input name="billing_<?=e($key)?>" maxlength="500"></label><?php endforeach ?></div><h2>Delivery method</h2><label class="radio-card"><input type="radio" name="shipping_method" value="standard" checked> Standard delivery · 3–5 working days <strong><?=$totals['shipping']?money($totals['shipping']):'Free'?></strong></label><h2>Payment</h2><label class="radio-card"><input type="radio" name="payment_method" value="cod" checked> Cash on delivery <small>Pay when your order arrives</small></label><label>Order notes <span class="muted">(optional)</span><textarea name="notes" maxlength="2000"></textarea></label><label class="check"><input type="checkbox" name="terms" value="1" required> I agree to the <a href="/terms">terms & conditions</a> and <a href="/privacy">privacy policy</a>.</label><button class="btn full">Place order · <?=money($totals['total'])?> ↗</button></form><aside class="order-summary"><h2>In your bag</h2><?php foreach($items as $i): ?><div class="mini-item"><img src="<?=e(image_path($i))?>" alt="<?=e($i['name'])?>" width="70" height="88"><div><strong><?=e($i['name'])?></strong><small><?=e(trim($i['size'].' '.$i['color'].' '.$i['volume']))?> · Qty <?=e($i['quantity'])?></small></div><span><?=money($i['line_total'])?></span></div><?php endforeach ?><?php require ROOT.'/views/partials/totals.php'; ?><a class="underlined" href="/cart">Edit bag or apply a coupon</a></aside></div><?php endif ?></section>
